  assert.ok(!result.ok);
  assert.strictEqual(result.error, 'DISCOUNT_INVALID');
});

test('removeLine preserves discounts on remaining lines', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 20 },
