  assert.ok(result.ok);
  assert.strictEqual(result.value.lines[0].sku, 'DEV-HOUR');
  assert.strictEqual(result.value.lines[0].discountPercent, 20);
});

test('issueInvoice with discounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
