  assert.ok(result.ok);
  assert.strictEqual(result.value.lines[0].discountPercent, 10);
  assert.strictEqual(result.value.status, 'issued');
});

test('amounts are clamped to zero (no negatives)', () => {
  const line = { qty: 0, unitPrice: 1000 };
  assert.ok(lineTotal(line) >= 0);
  assert.ok(lineDiscount(line) >= 0);

  const invoice = {
    lines: [
      { qty: 0, unitPrice: 1000 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.ok(totals.subtotal >= 0);
  assert.ok(totals.discount >= 0);
  assert.ok(totals.total >= 0);
});

